class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def list_length(head):
    count = 0
    while head is not None:
        count += 1
        head = head.next
    return count

def sum_list(head):
    total = 0
    while head is not None:
        total += head.val
        head = head.next
    return total

chain = Node(1, Node(2, Node(3)))
print(list_length(chain), sum_list(chain))
print(list_length(None), sum_list(None))

